CREATE TABLE roles(id text PRIMARY KEY, permissions text[] NOT NULL);
INSERT INTO roles VALUES ('owner',ARRAY['products','orders','customers','content','settings','users','audit','coupons']),('manager',ARRAY['products','orders','customers','content','coupons']),('support',ARRAY['orders','customers']);
CREATE TABLE admin_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,role_id text NOT NULL REFERENCES roles(id),active boolean NOT NULL DEFAULT true,mfa_required boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text UNIQUE NOT NULL,admin_id uuid REFERENCES admin_users(id),csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON sessions(expires_at);
CREATE TABLE password_resets(token_hash text PRIMARY KEY,admin_id uuid NOT NULL REFERENCES admin_users(id),expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name_en text NOT NULL,name_ar text NOT NULL,slug text UNIQUE NOT NULL);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sku text UNIQUE NOT NULL,slug text UNIQUE NOT NULL,name_en text NOT NULL,name_ar text NOT NULL,description_en text NOT NULL,description_ar text NOT NULL,volume text NOT NULL,category_id uuid REFERENCES categories(id),price integer CHECK(price>0 AND price<=100000000),currency text NOT NULL DEFAULT 'EGP' CHECK(currency='EGP'),status text NOT NULL DEFAULT 'inactive' CHECK(status IN ('active','inactive','archived')),usage_en text NOT NULL DEFAULT '',usage_ar text NOT NULL DEFAULT '',warnings_en text NOT NULL DEFAULT '',warnings_ar text NOT NULL DEFAULT '',inci text NOT NULL DEFAULT '',seo_title text NOT NULL DEFAULT '',seo_description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON products(status,category_id);
CREATE TABLE product_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),url text NOT NULL,alt_en text NOT NULL,alt_ar text NOT NULL,position integer NOT NULL DEFAULT 0);
CREATE INDEX ON product_images(product_id,position);
CREATE TABLE inventory(product_id uuid PRIMARY KEY REFERENCES products(id),stock integer NOT NULL DEFAULT 0 CHECK(stock>=0 AND stock<=1000000),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,mobile text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON customers(email);
CREATE TABLE addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers(id),governorate text NOT NULL,city text NOT NULL,street text NOT NULL,building text NOT NULL DEFAULT '',floor text NOT NULL DEFAULT '',apartment text NOT NULL DEFAULT '');
CREATE TABLE carts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid UNIQUE NOT NULL REFERENCES sessions(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cart_items(cart_id uuid NOT NULL REFERENCES carts(id),product_id uuid NOT NULL REFERENCES products(id),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99),PRIMARY KEY(cart_id,product_id));
CREATE TABLE coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,type text NOT NULL CHECK(type IN ('fixed','percent')),value integer NOT NULL CHECK(value>0 AND value<=100000000),active boolean NOT NULL DEFAULT false,starts_at timestamptz,ends_at timestamptz,usage_limit integer NOT NULL CHECK(usage_limit>0),used integer NOT NULL DEFAULT 0 CHECK(used>=0),minimum integer NOT NULL DEFAULT 0 CHECK(minimum>=0),CHECK(type<>'percent' OR value<=10000));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reference text UNIQUE NOT NULL,session_id uuid NOT NULL REFERENCES sessions(id),customer_id uuid NOT NULL REFERENCES customers(id),address_id uuid NOT NULL REFERENCES addresses(id),tracking_hash text UNIQUE NOT NULL,idempotency_key uuid NOT NULL,request_hash text NOT NULL,status text NOT NULL CHECK(status IN ('pending','paid','processing','shipped','delivered','cancelled','refunded')),payment_method text NOT NULL CHECK(payment_method IN ('cod','card')),subtotal integer NOT NULL CHECK(subtotal>0),discount integer NOT NULL CHECK(discount>=0),shipping integer NOT NULL CHECK(shipping>=0),total integer NOT NULL CHECK(total>0),currency text NOT NULL DEFAULT 'EGP',coupon_id uuid REFERENCES coupons(id),notes text NOT NULL DEFAULT '',locale text NOT NULL DEFAULT 'en',stock_released boolean NOT NULL DEFAULT false,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,idempotency_key),CHECK(total=subtotal-discount+shipping));
CREATE INDEX ON orders(created_at DESC);CREATE INDEX ON orders(status,expires_at);
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),product_id uuid NOT NULL REFERENCES products(id),sku text NOT NULL,name_en text NOT NULL,name_ar text NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99),unit_price integer NOT NULL CHECK(unit_price>0));
CREATE INDEX ON order_items(order_id);
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE NOT NULL REFERENCES orders(id),provider_id text UNIQUE,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded')),amount integer NOT NULL,currency text NOT NULL DEFAULT 'EGP',checkout_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid UNIQUE NOT NULL REFERENCES orders(id),provider_id text UNIQUE,tracking_id text,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events(provider text NOT NULL,event_id text NOT NULL,payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,event_id));
CREATE TABLE content(key text PRIMARY KEY,title_en text NOT NULL DEFAULT '',title_ar text NOT NULL DEFAULT '',body_en text NOT NULL DEFAULT '',body_ar text NOT NULL DEFAULT '',published boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE store_settings(id integer PRIMARY KEY CHECK(id=1),enabled boolean NOT NULL DEFAULT false,cod_enabled boolean NOT NULL DEFAULT true,phone text NOT NULL DEFAULT '01039010190',instagram text NOT NULL DEFAULT 'soleababy.egypt',shipping_rates jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO store_settings(id) VALUES(1);
CREATE TABLE subscribers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,consent_at timestamptz NOT NULL DEFAULT now(),active boolean NOT NULL DEFAULT true);
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,order_id uuid REFERENCES orders(id),payload jsonb NOT NULL DEFAULT '{}',dedupe_key text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,next_at timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON outbox(status,next_at);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid REFERENCES admin_users(id),action text NOT NULL,entity text NOT NULL,entity_id text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON audit_logs(created_at DESC);
